# Generated by Phase: IMPLEMENT | Feature: EVOL-069
"""Frontmatter lock (EVOL-069): an approved artefact's frontmatter changes only through its permitted transitions.

A file changed in the diff (the tree on disk against the merge-base with the diff base) whose BASE frontmatter
`status` is approved (planning.APPROVED_STATES) — markdown or .feature only — is compared key by key with its frontmatter on disk. A top-level
key added, removed or changed is red unless it is in PERMITTED (iteration state — LAW-09 —, build counters,
persistence, approval) or the change is a refine — an iteration appended, read through the one reader
(common.iteration_state); `status` may move only to a value of STATES. A new file is not this gate's.

A delivered artefact is never deleted (EVOL-072, DC-38): a markdown or .feature file that leaves the diff — deleted,
replaced by a non-file (a link), or moved to a name that is no artefact — whose BASE `status` is delivered
(APPROVED_STATES or MERGED) or terminal (CANCELLED / SUPERSEDED: the trace it keeps) is red. A move to another
markdown or .feature name keeps the artefact (renames detected). A base frontmatter the parser cannot read is still
judged: its `status:` line is read directly (a gate that cannot read never reads green).
"""
from __future__ import annotations

import re
import subprocess
from pathlib import Path

from .common import GateFault, frontmatter_of, iteration_state, read_frontmatter
from .planning import APPROVED_STATES
from .seal import _git, _reference

PERMITTED = frozenset({
    # iteration state (LAW-09)
    "iterations", "iteration", "iteration_history", "last_iteration_scope", "pending_iteration", "pending_reason",
    "cascade_source", "cascade_timestamp", "cascade_scope", "invalidated_sections", "invalidated_increments",
    "invalidated_slices", "invalidated_by", "invalidated_by_iteration", "invalidated_reason", "invalidated_at",
    "pending_schemas_version", "schemas_version", "based_on_iteration", "based_on_schemas_version", "delta_mode",
    "delta_tasks_added",
    # build counters (`increments`: dev_plan's per-increment status mirror, written by IMPLEMENT --plan / --build)
    "increments", "total_tasks", "tasks_completed", "tasks_skipped", "tasks_total", "completed_at", "verification",
    "fix_cycle", "fix_tasks_added",
    # persistence
    "_progress", "updated_at", "last_update",
    # a refine's carry-over (BLUEPRINT --refine appends it)
    "pending_design_items",
    # approval (#134)
    "approved_at", "approved_by",
    # the status, within STATES
    "status",
})

STATES = frozenset(s.upper() for s in (
    "DRAFT", "NEEDS_INFO", "APPROVED", "BLOCKED", "BUILDING", "IMPLEMENTED_AND_VERIFIED", "CASCADE_PENDING_ITERATION",
    "REJECTED", "CANCELLED", "SUPERSEDED", "APPROVED (SUPERSEDED)", "INVALIDATED", "READY", "MERGED", "proposed", "accepted",
))

RESOLUTION = "change it through the phase's refine, which appends an iteration"
DELIVERED = APPROVED_STATES | {"MERGED"}
KEPT = DELIVERED | {"CANCELLED", "SUPERSEDED", "APPROVED (SUPERSEDED)"}   # never deleted: delivered, or terminal
ARTEFACT = (".md", ".feature")
TEMPLATES = ".context/templates/"   # a template is never an artefact: its status is the materialised default (EVOL-118)
STATUS_LINE = re.compile(r"^status:[ \t]*['\"]?([^'\"#\r\n]*)", re.M)


def _status(fm: dict) -> str:
    s = fm.get("status")
    return s.strip().upper() if isinstance(s, str) else ""   # by type: never the repr of an aliased structure


def _base_status(text: str) -> str:
    """The base's status; the `status:` line of the frontmatter block when the parser cannot read it."""
    try:
        return _status(frontmatter_of(text))
    except (GateFault, RecursionError):
        block = re.match(r"---\r?\n(.*?)\r?\n---", text, re.S)
        m = STATUS_LINE.search(block.group(1)) if block else None
        return m.group(1).strip().upper() if m else ""


def _gone(repo: Path, ref: str) -> list[str]:
    """The artefacts that leave the diff: deleted, type-changed (a link in place of the file), or renamed to a non-artefact."""
    out, f = [], _git(repo, "diff", "--name-status", "-z", "-M", ref).split("\0")
    i = 0
    while i < len(f) - 1:
        st = f[i]
        if st[:1] in ("R", "C"):
            old, new = f[i + 1], f[i + 2]
            i += 3
            if st[:1] == "R" and old.endswith(ARTEFACT) and not new.endswith(ARTEFACT) and not old.startswith(TEMPLATES):
                out.append(old)
            continue
        path = f[i + 1]
        i += 2
        if st[:1] in ("D", "T") and path.endswith(ARTEFACT) and not path.startswith(TEMPLATES):
            out.append(path)
    return out


def _at(repo: Path, ref: str, path: str) -> str | None:
    """The file's text at `ref`; None when it does not exist there."""
    r = subprocess.run(["git", "-C", str(repo), "show", f"{ref}:{path}"], capture_output=True, text=True, errors="replace", timeout=60)
    return r.stdout if r.returncode == 0 else None


def check(repo: Path, base: str) -> list[dict]:
    """[{path, key, reason}] — one per key changed outside the permitted transitions. GateFault on an unreadable base."""
    ref = _reference(repo, base)
    findings = []
    for path in _gone(repo, ref):
        status = _base_status(_at(repo, ref, path) or "")
        if status in KEPT:
            findings.append({"path": path, "key": "(deleted)", "reason": f"a delivered artefact ({status}) was deleted — "
                             "mark it terminal (status CANCELLED or SUPERSEDED) and keep the file; never delete it" if status in DELIVERED else
                             f"a terminal artefact ({status}) was deleted — it is the trace of what was decided; keep the file"})
    for path in [p for p in _git(repo, "diff", "--name-only", "--no-renames", ref).splitlines() if p.endswith(ARTEFACT) and not p.startswith(TEMPLATES)]:
        disk = repo / path   # an approved artefact is markdown or a spec.feature: a binary or a YAML document is not this gate's
        if not disk.is_file():
            continue  # deleted or no longer a file: judged above
        before_text = _at(repo, ref, path)
        if before_text is None:
            continue
        try:
            before = frontmatter_of(before_text)
        except GateFault:
            continue  # unreadable at the base: never an approved artefact the lock can compare
        if _status(before) not in APPROVED_STATES:
            continue
        try:
            after = read_frontmatter(disk)
        except GateFault as e:
            findings.append({"path": path, "key": "(frontmatter)", "reason": f"the frontmatter no longer parses ({e}) on an approved artefact — {RESOLUTION}"})
            continue
        refined = len(iteration_state(after)["history"]) > len(iteration_state(before)["history"])   # the refine's record (LAW-09)
        for k in sorted(set(before) | set(after)):
            if before.get(k) == after.get(k) and (k in before) == (k in after):
                continue
            if k == "status":
                if _status(after) in STATES:
                    continue
                why = f"status moved to {after.get('status')!r}, outside the closed state vocabulary"
            elif k in PERMITTED or refined:
                continue
            else:
                why = f"key `{k}` was {'added' if k not in before else 'removed' if k not in after else 'changed'}"
            findings.append({"path": path, "key": k, "reason": f"{why} on an approved artefact — {RESOLUTION}"})
    return findings
